// External references require Symbol Resolution
// Linker must find definition of 'ext_data' in another object file
extern int ext_data;

// Compiler generates instruction code that references 'ext_data'
// This address will be marked with a Relocation Entry
int use_data() {
    return ext_data + 1;
}

// --- Relocation Entry Structure (e.g., ELF Rela) ---
typedef struct {
    uint64_t r_offset;  // Address offset within the section needing fixup
    uint64_t r_info;    // Type (32 bits) | Symbol Index (32 bits)
    int64_t  r_addend;  // Constant value added to the final address
} Elf_Rela;

// Common Relocation Types (How to calculate the final value V)
// PC32: V = Symbol_Value + Addend - Offset_of_Reference (For PIC)
// ABS64: V = Symbol_Value + Addend (For absolute addressing)

// --- Handling Unknown Final Address (Global Offset Table/PIC) ---
// The loader/runtime linker fixes GOT entries using relocation entries.
void fixup_got_entry(Elf_Rela entry, uintptr_t resolved_sym_addr) {
    uintptr_t* got_slot = (uintptr_t*)(
        module_load_base + entry.r_offset
    );
    // Write the final, known address into the indirection table slot
    *got_slot = resolved_sym_addr + entry.r_addend;
}
